import{_ as t,o as s,c as i,a2 as a}from"./chunks/framework.Cdp8-jB6.js";const p=JSON.parse('{"title":"Adding a new mission — runbook","description":"","frontmatter":{},"headers":[],"relativePath":"guides/mission-addition-runbook.md","filePath":"guides/mission-addition-runbook.md"}'),o={name:"guides/mission-addition-runbook.md"};function n(r,e,d,l,h,c){return s(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="adding-a-new-mission-—-runbook" tabindex="-1">Adding a new mission — runbook <a class="header-anchor" href="#adding-a-new-mission-—-runbook" aria-label="Permalink to &quot;Adding a new mission — runbook&quot;">​</a></h1><p>The single prescribed path for bringing a new mission&#39;s content (text · links · flight · images · translations) into Orrery. Analogous to <a href="./../../scripts/IMAGE-PIPELINE"><code>scripts/IMAGE-PIPELINE.md</code></a> &quot;Adding a new gallery image&quot; and the AGENTS.md &quot;Adding a new flyby body&quot; checklist. <strong>Read this before hand-authoring mission JSON.</strong></p><p>Worked example throughout: <strong>Artemis 4</strong> (<code>artemis4</code>, a planned NASA Moon mission), added 2026-07-10.</p><h2 id="the-model-—-mostly-hand-authored-json-gated-by-validate-data" tabindex="-1">The model — mostly hand-authored JSON, gated by <code>validate-data</code> <a class="header-anchor" href="#the-model-—-mostly-hand-authored-json-gated-by-validate-data" aria-label="Permalink to &quot;The model — mostly hand-authored JSON, gated by \`validate-data\`&quot;">​</a></h2><p>There is <strong>no <code>add-mission</code> script</strong> — a mission is static JSON validated by fail-closed gates. <strong><code>npm run validate-data</code> is your checklist</strong>: it names every missing/asymmetric touchpoint (often with the exact fix command). Author → <code>validate-data</code> → fix what it flags → repeat until green. Multi-device is automatic: <code>static/data</code> is bundled into the iOS/Android apps and renders on mobile + TV through the same components — no per-device step.</p><h3 id="design-intent-—-derive-integrity-source-images-but-never-fabricate-content" tabindex="-1">Design intent — derive integrity + source images, but never fabricate content <a class="header-anchor" href="#design-intent-—-derive-integrity-source-images-but-never-fabricate-content" aria-label="Permalink to &quot;Design intent — derive integrity + source images, but never fabricate content&quot;">​</a></h3><p>The process should do more of the mechanical work for you, along one clear line — <strong>derive/source where the answer is unambiguous; block-and-prompt where it&#39;s real content that needs authoring + approval</strong>:</p><ul><li><strong>Integrity is auto-derived (do it, don&#39;t ask).</strong> Fleet-ref <strong>symmetry</strong> (<code>linked_missions</code>) is pure derivation from <code>fleet_refs</code> — the add flow should run <code>migrate-fleet-linked-missions.ts</code> for you, not make you chase a <code>validate-data</code> failure. Same for any manifest that&#39;s a function of disk (gallery counts).</li><li><strong>Images are auto-<em>sourced to staging</em> (attempt, then human-approve).</strong> The add flow should kick off the agency-first fetch for the hero + gallery <strong>into <code>_staging/</code></strong> for review at <code>/dev/staging</code> — &quot;to some extent where possible&quot; (rich for flown missions, agency <strong>concept art</strong> for future ones like Artemis 4). It never auto-ships: per-image approval stands (AGENTS.md), and the WebP/masters derive + provenance run only after promotion.</li><li><strong>New fleet <em>records</em> are NOT auto-created — they&#39;re detected + blocked.</strong> When a mission references a fleet asset that doesn&#39;t exist (Artemis 4 wants <code>sls-block-1b</code> / <code>gateway</code> / <code>i-hab</code> / <code>starship-hls</code>), the process must say &quot;author these first&quot; — <strong>not</strong> stub them. An auto-generated fleet entry is a bare stub (specs/agency/images/provenance all empty), the exact rot AGENTS.md&#39;s five-gate rule exists to stop. Adding a mission that needs a new launcher is legitimately <em>two</em> authoring tasks.</li></ul><p>Net: <code>validate-data</code> flagging a missing fleet asset is correct — but the <em>fix</em> for <strong>symmetry</strong> should be automatic, while the fix for a <strong>missing fleet record</strong> should be an explicit prompt to author it.</p><h2 id="touchpoints-in-order" tabindex="-1">Touchpoints (in order) <a class="header-anchor" href="#touchpoints-in-order" aria-label="Permalink to &quot;Touchpoints (in order)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Touchpoint</th><th>File</th><th>Required</th><th>Fix / script</th></tr></thead><tbody><tr><td>1</td><td><strong>Base record</strong></td><td><code>static/data/missions/&lt;dest_lower&gt;/&lt;id&gt;.json</code></td><td>✅</td><td>schema <code>mission.schema.json</code></td></tr><tr><td>2</td><td><strong>Index entry</strong></td><td><code>static/data/missions/index.json</code></td><td>✅</td><td>schema <code>mission-index.schema.json</code></td></tr><tr><td>3</td><td><strong>en-US overlay</strong></td><td><code>i18n-src/en-US/missions/&lt;dest&gt;/&lt;id&gt;.json</code></td><td>✅</td><td>schema <code>mission-overlay.schema.json</code></td></tr><tr><td>4</td><td><strong>LEARN links</strong></td><td><code>links[]</code> in the base record</td><td>✅ (≥1)</td><td><code>npm run check-learn-links -- --update</code> (ADR-051)</td></tr><tr><td>5</td><td><strong>Fleet cross-refs</strong></td><td><code>fleet_refs[]</code> in base record</td><td>optional</td><td><strong><code>npx tsx scripts/migrate-fleet-linked-missions.ts</code></strong> (derives the reverse <code>linked_missions[]</code> — symmetry is fail-closed)</td></tr><tr><td>6</td><td><strong>Flight + trajectory</strong></td><td><code>flight.*</code> + generated <code>waypoints_km</code> / <code>waypoints_helio_au</code></td><td>optional (needed for <code>/fly</code>)</td><td>Moon: <code>generate-hybrid-waypoints.ts</code>; Mars/outer: <code>generate-helio-hybrid-waypoints.ts</code></td></tr><tr><td>7</td><td><strong>Hero + gallery images</strong></td><td><code>static/images/missions/&lt;id&gt;/…</code></td><td>✅ hero (zero-gap policy)</td><td>the image pipeline — see below</td></tr><tr><td>8</td><td><strong>Translations (all 14 locales)</strong></td><td><code>i18n-src/&lt;locale&gt;/missions/&lt;dest&gt;/&lt;id&gt;.json</code></td><td>✅ <strong>required</strong> (core content)</td><td><code>scripts/translate-i18n-gaps.mjs</code></td></tr></tbody></table><h3 id="_1–3-·-core-data" tabindex="-1">1–3 · Core data <a class="header-anchor" href="#_1–3-·-core-data" aria-label="Permalink to &quot;1–3 · Core data&quot;">​</a></h3><p>Base record required fields (<code>mission.schema.json</code>): <code>id, agency, agency_full, sector, dest, color, year, status, departure_date, arrival_date, transit_days, vehicle, payload, delta_v, data_quality, credit, links</code>. Index required: <code>id, agency, dest, status, year, sector, color</code> (+ <code>crewed</code>). Overlay required: <code>name, type, first, description</code>. <code>id</code> is <code>^[a-z0-9-]+$</code>; <code>dest</code> must match the file-path destination. Copy the shape from the nearest analog (Artemis 4 was authored from <code>artemis3.json</code>).</p><h3 id="_5-·-fleet-refs-—-author-new-fleet-entries-first" tabindex="-1">5 · Fleet refs — author new fleet entries FIRST <a class="header-anchor" href="#_5-·-fleet-refs-—-author-new-fleet-entries-first" aria-label="Permalink to &quot;5 · Fleet refs — author new fleet entries FIRST&quot;">​</a></h3><p><code>fleet_refs[]</code> must point at <strong>existing</strong> fleet entries; a new launcher/spacecraft (Artemis 4 really wants <code>sls-block-1b</code>, <code>gateway</code>, <code>i-hab</code>, <code>starship-hls</code> — none exist yet) must be authored via the <a href="./fleet-addition-runbook">fleet-addition runbook</a> <strong>before</strong> you can reference it (an agent can fan out one sub-agent per missing asset). Never stub them. Then run <code>migrate-fleet-linked-missions.ts</code> to populate the reverse pointers (symmetry is fail-closed). <em>In the Artemis 4 dogfood we reused <code>sls-block-1</code> + <code>orion</code> + <code>lc-39b</code>; the Block 1B / Gateway / I-HAB fleet entries are a follow-up.</em></p><h3 id="_6-·-flight-data-is-optional-—-but-nothing-warns-you-fly-is-empty" tabindex="-1">6 · Flight data is OPTIONAL — but nothing warns you <code>/fly</code> is empty <a class="header-anchor" href="#_6-·-flight-data-is-optional-—-but-nothing-warns-you-fly-is-empty" aria-label="Permalink to &quot;6 · Flight data is OPTIONAL — but nothing warns you \`/fly\` is empty&quot;">​</a></h3><p>A mission validates with <strong>no</strong> <code>flight</code> block; it just renders on <code>/missions</code> and not on <code>/fly</code>. If you want the <code>/fly</code> trajectory, add <code>flight.*</code> (launch/cruise/arrival/totals/events + <code>cislunar_profile</code> for Moon or <code>interplanetary_profile</code> for Mars/outer) <strong>and generate the waypoints</strong> — the geometry won&#39;t render without them:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tsx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/cislunar/generate-hybrid-waypoints.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> static/data/missions/moon/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.json</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # Moon</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tsx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/cislunar/generate-helio-hybrid-waypoints.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> static/data/missions/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">des</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.json</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # Mars / outer</span></span></code></pre></div><p><strong>Flight-internal consistency (validate-data fails-closed).</strong> The flight block must be self-consistent — most notably <strong><code>cruise.tcm_count</code> must equal the number of <code>events[]</code> with <code>type: &quot;tcm&quot;</code></strong> (caught in the Hera dogfood: <code>✗ tcm_count=2 but events.tcm.length=0</code>). Add the matching <code>tcm</code> events, or set the count to match. Event <code>met_days</code> must be ordered + within the transit; <code>events[].type</code> must be in the schema enum. Re-run the waypoint generator after editing events (it re-pins event anchors). The generator does a <strong>parametric Lambert transfer</strong> — a mission with a real gravity assist (Hera&#39;s 2025 Mars flyby) is approximated, hence <code>flight_data_quality: sparse</code> + <code>source_tier: tier_1_5_hybrid</code>.</p><p><strong>Trajectory thumbnail — REQUIRED once flight data exists (#390, validate-data fails-closed).</strong> <code>static/images/missions/thumbnails/&lt;id&gt;.png</code> — a 240×120 node-canvas render of the flight path, shown in the mission panel. Rendered by the thumbnail step in <code>scripts/fetch-assets.ts</code> (NOT part of <code>npm run build</code>), so run it explicitly after adding/editing flight data:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tsx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/fetch-assets.ts</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --thumbnails-only</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # renders all mission thumbnails; commit only &lt;id&gt;.png</span></span></code></pre></div><p>Every flight-block mission is renderable — MOON → cislunar; a mission with generated waypoints → Sun-centric path; a planetary porkchop body → transfer arc; and generic SUN/COMET/ASTEROID destinations → a per-mission analytic heliocentric distance (<code>ANALYTIC_HELIO_AU</code> in <code>fetch-assets.ts</code>, real astronomical figures — add an entry for a new analytic destination or the gate lists it). The <code>validate-data</code> gate fails closed if a <code>flight</code> mission has no <code>thumbnails/&lt;id&gt;.png</code> — parity with the hero zero-gap + i18n gates. <em>(Re-rendering is byte-noisy — <code>git checkout --</code> the churn and commit only your mission&#39;s new PNG.)</em></p><p><strong>Optional <code>/fly</code> polish (not gated):</strong></p><ul><li><strong><code>/fly</code> camera</strong> <code>static/data/fly-camera-audit.json</code> — a per-mission camera-framing entry. Absent → <code>/fly</code> uses a sensible default (not broken, just untuned). Add one only if the default framing is poor.</li></ul><h3 id="_7-·-images-—-missions-carry-zero-hero-gaps" tabindex="-1">7 · Images — missions carry ZERO hero gaps <a class="header-anchor" href="#_7-·-images-—-missions-carry-zero-hero-gaps" aria-label="Permalink to &quot;7 · Images — missions carry ZERO hero gaps&quot;">​</a></h3><p><code>validate-hero-coverage</code> fails-closed if <code>static/images/missions/&lt;id&gt;/01.webp</code> is absent (<code>MISSIONS_KNOWN_GAPS</code> is intentionally empty since #342). Source the hero + gallery through the <strong><a href="./../../scripts/IMAGE-PIPELINE#adding-a-new-gallery-image">image pipeline runbook</a></strong>: source (agency-first) → <code>masters/</code> (git-LFS) → WebP ladder + 1x1 → provenance → gallery counts. For a <strong>future mission</strong> with no photos (Artemis 4), the hero is agency <strong>concept art</strong> — same pipeline, and <strong>image changes need per-image approval</strong> (see AGENTS.md).</p><h3 id="_8-·-translations-—-core-content-not-optional" tabindex="-1">8 · Translations — CORE content, not optional <a class="header-anchor" href="#_8-·-translations-—-core-content-not-optional" aria-label="Permalink to &quot;8 · Translations — CORE content, not optional&quot;">​</a></h3><p><strong>Localization is content work — the same tier as sourcing the hero image, and it cannot be skipped.</strong> All 14 locales must be authored before the mission is done. <code>validate-data</code> currently only <em>enforces</em> the en-US overlay (the other 13 fall back to English at runtime so nothing hard-breaks), but a mission that renders English into 13 locales is <strong>not shipped — it&#39;s half-authored</strong>. Fill them in the same PR:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">set</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -a</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">source</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +a</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/translate-i18n-gaps.mjs</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # scans for missing locale overlays + fills them (Claude API, ADR-033)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> i18n:compile</span></span></code></pre></div><blockquote><p>The en-US-only floor in <code>validate-data</code> is a fallback safety net, <strong>not</strong> the done-bar. A green <code>validate-data</code> with missing translations is as unfinished as a missing hero image.</p></blockquote><h2 id="validation-the-done-signal" tabindex="-1">Validation = the done-signal <a class="header-anchor" href="#validation-the-done-signal" aria-label="Permalink to &quot;Validation = the done-signal&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> validate-data</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # schema + overlay-completeness + fleet symmetry + hero coverage + links</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> preflight</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # full pre-push (typecheck → lint → test → validate → build)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> preview</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           # eyeball /missions card + /fly (if flight data) at localhost</span></span></code></pre></div><p>Each <code>validate-data</code> failure names the touchpoint and usually the fix command — treat it as the interactive checklist.</p><h2 id="gotchas-learned-in-the-artemis-4-dogfood" tabindex="-1">Gotchas (learned in the Artemis 4 dogfood) <a class="header-anchor" href="#gotchas-learned-in-the-artemis-4-dogfood" aria-label="Permalink to &quot;Gotchas (learned in the Artemis 4 dogfood)&quot;">​</a></h2><ul><li><strong>New fleet deps cascade.</strong> An accurate mission often needs new fleet entries authored first (Block 1B / Gateway / I-HAB). Reuse existing entries only when honest.</li><li><strong><code>fleet_refs</code> are one-directional until you run the migrate script</strong> — symmetry is fail-closed; the error even prints the command.</li><li><strong><code>flight</code> optional + no <code>/fly</code> warning</strong> — a mission can ship looking complete while <code>/fly?mission=&lt;id&gt;</code> is empty because waypoints were never generated.</li><li><strong>Hero image is mandatory</strong> (zero-gap policy) — you cannot ship a mission without one; for future missions that means sourcing concept art through the approval-gated image pipeline.</li><li><strong>en-US passing CI is a floor, not done.</strong> Localization is core content (same tier as the hero image) — a mission rendering English into 13 locales is unfinished; run <code>translate-i18n-gaps.mjs</code> in the same PR.</li></ul>`,35)])])}const m=t(o,[["render",n]]);export{p as __pageData,m as default};
